create schema if not exists extensions;
create schema if not exists vault;

create extension if not exists pgcrypto with schema extensions;
create extension if not exists pg_trgm with schema extensions;
create extension if not exists pg_net;
create extension if not exists pg_cron;
create extension if not exists supabase_vault with schema vault;

create type public.sync_item_type as enum ('anime','episode');
create type public.sync_status as enum ('pending','processing','completed','failed');
create type public.video_source_type as enum ('embed','hls','mp4','other');
create type public.title_kind as enum ('alternative','english','japanese','synonym');

create table public.anime (
  id uuid primary key default gen_random_uuid(), source_id text not null unique, source_url text not null unique, slug text not null unique, title text not null,
  title_english text, title_japanese text, description text, poster_url text, banner_url text, type text, status text, season text,
  year int check (year is null or year between 1900 and 2200), rating numeric(4,2), duration text, latest_episode numeric(10,2), total_episodes int,
  source_updated_at timestamptz, content_hash text, metadata_hash text, last_seen_at timestamptz not null default now(), last_scraped_at timestamptz,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table public.anime_titles (id bigint generated by default as identity primary key, anime_id uuid not null references public.anime(id) on delete cascade, kind public.title_kind not null default 'alternative', title text not null, normalized_title text generated always as (lower(regexp_replace(title, '[^[:alnum:]]+', ' ', 'g'))) stored, unique(anime_id, kind, title));
create table public.episodes (id uuid primary key default gen_random_uuid(), anime_id uuid not null references public.anime(id) on delete cascade, source_episode_id text not null unique, source_url text not null unique, episode_number numeric(10,2) not null, title text, thumbnail_url text, air_date timestamptz, content_hash text, metadata_hash text, last_seen_at timestamptz not null default now(), last_scraped_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(anime_id, episode_number));
create table public.video_sources (id uuid primary key default gen_random_uuid(), episode_id uuid not null references public.episodes(id) on delete cascade, server_name text not null, source_type public.video_source_type not null default 'other', embed_url text, stream_url text, quality text, language text, is_active boolean not null default true, verification_failures int not null default 0, last_verified_at timestamptz, source_hash text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check (embed_url is not null or stream_url is not null), unique nulls not distinct (episode_id, server_name, source_type, embed_url, stream_url, quality, language));
create table public.genres (id bigint generated by default as identity primary key, name text not null unique, slug text not null unique);
create table public.anime_genres (anime_id uuid not null references public.anime(id) on delete cascade, genre_id bigint not null references public.genres(id) on delete cascade, primary key(anime_id, genre_id));
create table public.studios (id bigint generated by default as identity primary key, name text not null unique, slug text not null unique);
create table public.anime_studios (anime_id uuid not null references public.anime(id) on delete cascade, studio_id bigint not null references public.studios(id) on delete cascade, primary key(anime_id, studio_id));
create table public.characters (id uuid primary key default gen_random_uuid(), source_id text unique, name text not null, image_url text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.anime_characters (anime_id uuid not null references public.anime(id) on delete cascade, character_id uuid not null references public.characters(id) on delete cascade, role text, primary key(anime_id, character_id));
create table public.voice_actors (id uuid primary key default gen_random_uuid(), source_id text unique, name text not null, language text, image_url text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.character_voice_actors (anime_id uuid not null references public.anime(id) on delete cascade, character_id uuid not null references public.characters(id) on delete cascade, voice_actor_id uuid not null references public.voice_actors(id) on delete cascade, language text, primary key(anime_id, character_id, voice_actor_id, language));
create table public.related_anime (anime_id uuid not null references public.anime(id) on delete cascade, related_anime_id uuid not null references public.anime(id) on delete cascade, relation_type text not null default 'related', primary key(anime_id, related_anime_id, relation_type), check (anime_id <> related_anime_id));
create table public.source_items (source_url text primary key, source_id text not null, item_type public.sync_item_type not null, scanner_hash text not null, last_seen_at timestamptz not null default now(), last_queued_at timestamptz, created_at timestamptz not null default now());
create table public.sync_queue (id uuid primary key default gen_random_uuid(), source_url text not null, source_id text not null, item_type public.sync_item_type not null, status public.sync_status not null default 'pending', priority int not null default 100, attempts int not null default 0, max_attempts int not null default 5, last_error text, available_at timestamptz not null default now(), created_at timestamptz not null default now(), started_at timestamptz, completed_at timestamptz, updated_at timestamptz not null default now());
create unique index sync_queue_active_unique on public.sync_queue(source_url, item_type) where status in ('pending','processing');
create table public.sync_runs (id uuid primary key default gen_random_uuid(), run_type text not null default 'scan', started_at timestamptz not null default now(), finished_at timestamptz, items_scanned int not null default 0, new_anime int not null default 0, new_episodes int not null default 0, updated_anime int not null default 0, updated_episodes int not null default 0, errors int not null default 0, details jsonb not null default '{}'::jsonb);
create table public.sync_events (id bigint generated by default as identity primary key, run_id uuid references public.sync_runs(id) on delete set null, event_type text not null, source_url text, entity_id uuid, message text, details jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table public.profiles (user_id uuid primary key references auth.users(id) on delete cascade, display_name text, avatar_url text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.admin_users (user_id uuid primary key references auth.users(id) on delete cascade, created_at timestamptz not null default now());
create table public.favorites (user_id uuid not null references auth.users(id) on delete cascade, anime_id uuid not null references public.anime(id) on delete cascade, created_at timestamptz not null default now(), primary key(user_id, anime_id));
create table public.watch_history (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, anime_id uuid not null references public.anime(id) on delete cascade, episode_id uuid not null references public.episodes(id) on delete cascade, watched_at timestamptz not null default now(), unique(user_id, episode_id));
create table public.playback_progress (user_id uuid not null references auth.users(id) on delete cascade, episode_id uuid not null references public.episodes(id) on delete cascade, anime_id uuid not null references public.anime(id) on delete cascade, position_seconds numeric(12,3) not null default 0, duration_seconds numeric(12,3), completed boolean not null default false, updated_at timestamptz not null default now(), primary key(user_id, episode_id));

create index anime_title_trgm_idx on public.anime using gin (title gin_trgm_ops);
create index anime_english_trgm_idx on public.anime using gin (title_english gin_trgm_ops);
create index anime_japanese_trgm_idx on public.anime using gin (title_japanese gin_trgm_ops);
create index anime_status_idx on public.anime(status); create index anime_type_idx on public.anime(type); create index anime_year_idx on public.anime(year desc); create index anime_season_idx on public.anime(season); create index anime_updated_idx on public.anime(updated_at desc);
create index episodes_anime_number_idx on public.episodes(anime_id, episode_number desc); create index episodes_air_date_idx on public.episodes(air_date desc nulls last); create index video_sources_episode_active_idx on public.video_sources(episode_id, is_active); create index sync_queue_claim_idx on public.sync_queue(status, available_at, priority, created_at); create index sync_events_created_idx on public.sync_events(created_at desc); create index watch_history_user_time_idx on public.watch_history(user_id, watched_at desc); create index playback_progress_user_time_idx on public.playback_progress(user_id, updated_at desc);

create or replace function public.touch_updated_at() returns trigger language plpgsql as $$ begin new.updated_at = now(); return new; end $$;
create trigger anime_touch before update on public.anime for each row execute function public.touch_updated_at();
create trigger episodes_touch before update on public.episodes for each row execute function public.touch_updated_at();
create trigger video_sources_touch before update on public.video_sources for each row execute function public.touch_updated_at();
create trigger profiles_touch before update on public.profiles for each row execute function public.touch_updated_at();
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$ begin insert into public.profiles(user_id, display_name) values (new.id, coalesce(new.raw_user_meta_data->>'display_name', split_part(new.email,'@',1))) on conflict (user_id) do nothing; return new; end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path = public as $$ select exists(select 1 from public.admin_users where user_id = auth.uid()); $$;
create or replace function public.claim_sync_jobs(p_limit int default 5) returns setof public.sync_queue language plpgsql security definer set search_path=public as $$ begin update public.sync_queue q set status='processing', started_at=now(), updated_at=now(), attempts=attempts+1 where q.id in (select id from public.sync_queue where status='pending' and available_at <= now() order by priority asc, created_at asc for update skip locked limit greatest(1, least(p_limit, 20))) returning q.*; end $$;
create or replace function public.recover_stale_sync_jobs(p_age interval default interval '15 minutes') returns int language plpgsql security definer set search_path=public as $$ declare n int; begin update public.sync_queue set status='pending', started_at=null, available_at=now(), updated_at=now(), last_error=coalesce(last_error,'') || E'\nRecovered stale processing job.' where status='processing' and started_at < now() - p_age and attempts < max_attempts; get diagnostics n = row_count; return n; end $$;
create or replace function public.enqueue_sync_job(p_source_url text,p_source_id text,p_item_type public.sync_item_type,p_priority int default 100) returns uuid language plpgsql security definer set search_path=public as $$ declare out_id uuid; begin select id into out_id from public.sync_queue where source_url=p_source_url and item_type=p_item_type and status in ('pending','processing') limit 1; if out_id is not null then return out_id; end if; begin insert into public.sync_queue(source_url, source_id, item_type, priority) values(p_source_url,p_source_id,p_item_type,p_priority) returning id into out_id; exception when unique_violation then select id into out_id from public.sync_queue where source_url=p_source_url and item_type=p_item_type and status in ('pending','processing') order by created_at desc limit 1; end; return out_id; end $$;
create or replace view public.continue_watching with (security_invoker=true) as select p.user_id, p.anime_id, p.episode_id, p.position_seconds, p.duration_seconds, p.completed, p.updated_at, a.title as anime_title, a.slug, a.poster_url, e.episode_number, e.title as episode_title from public.playback_progress p join public.anime a on a.id=p.anime_id join public.episodes e on e.id=p.episode_id where not p.completed;

alter table public.anime enable row level security; alter table public.anime_titles enable row level security; alter table public.episodes enable row level security; alter table public.video_sources enable row level security; alter table public.genres enable row level security; alter table public.anime_genres enable row level security; alter table public.studios enable row level security; alter table public.anime_studios enable row level security; alter table public.characters enable row level security; alter table public.anime_characters enable row level security; alter table public.voice_actors enable row level security; alter table public.character_voice_actors enable row level security; alter table public.related_anime enable row level security; alter table public.source_items enable row level security; alter table public.sync_queue enable row level security; alter table public.sync_runs enable row level security; alter table public.sync_events enable row level security; alter table public.profiles enable row level security; alter table public.admin_users enable row level security; alter table public.favorites enable row level security; alter table public.watch_history enable row level security; alter table public.playback_progress enable row level security;
create policy catalog_anime_read on public.anime for select using (true); create policy catalog_titles_read on public.anime_titles for select using (true); create policy catalog_episodes_read on public.episodes for select using (true); create policy catalog_video_read on public.video_sources for select using (is_active or public.is_admin()); create policy catalog_genres_read on public.genres for select using (true); create policy catalog_anime_genres_read on public.anime_genres for select using (true); create policy catalog_studios_read on public.studios for select using (true); create policy catalog_anime_studios_read on public.anime_studios for select using (true); create policy catalog_characters_read on public.characters for select using (true); create policy catalog_anime_characters_read on public.anime_characters for select using (true); create policy catalog_voice_actors_read on public.voice_actors for select using (true); create policy catalog_character_va_read on public.character_voice_actors for select using (true); create policy catalog_related_read on public.related_anime for select using (true);
create policy own_profile_select on public.profiles for select using (auth.uid()=user_id or public.is_admin()); create policy own_profile_update on public.profiles for update using (auth.uid()=user_id) with check (auth.uid()=user_id); create policy own_admin_membership on public.admin_users for select using (auth.uid()=user_id); create policy own_favorites_all on public.favorites for all using (auth.uid()=user_id) with check (auth.uid()=user_id); create policy own_history_all on public.watch_history for all using (auth.uid()=user_id) with check (auth.uid()=user_id); create policy own_progress_all on public.playback_progress for all using (auth.uid()=user_id) with check (auth.uid()=user_id);
create policy admin_source_items on public.source_items for select using (public.is_admin()); create policy admin_sync_queue on public.sync_queue for select using (public.is_admin()); create policy admin_sync_queue_update on public.sync_queue for update using (public.is_admin()) with check (public.is_admin()); create policy admin_sync_runs on public.sync_runs for select using (public.is_admin()); create policy admin_sync_events on public.sync_events for select using (public.is_admin());
grant execute on function public.is_admin() to authenticated, anon; grant execute on function public.claim_sync_jobs(int) to service_role; grant execute on function public.recover_stale_sync_jobs(interval) to service_role; grant execute on function public.enqueue_sync_job(text,text,public.sync_item_type,int) to service_role; revoke all on public.source_items, public.sync_queue, public.sync_runs, public.sync_events from anon;
